/* Build-time helper: turns stdlib/*.sp into a C table of bundled Sprint modules.
 * usage: embedsrc OUT.c name=file.sp ... */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) return 2;
    FILE *out = fopen(argv[1], "w");
    if (!out) return 1;
    (void)fputs("/* generated by tools/embedsrc.c; do not edit */\n#include \"sp.h\"\n\n", out);
    for (int i = 2; i < argc; i++) {
        char *eq = strchr(argv[i], '=');
        if (!eq) return 2;
        FILE *in = fopen(eq + 1, "rb");
        if (!in) { (void)fprintf(stderr, "embedsrc: cannot open %s\n", eq + 1); return 1; }
        (void)fprintf(out, "static const char src_%d[] = {", i - 2);
        int c, n = 0;
        while ((c = fgetc(in)) != EOF) (void)fprintf(out, "%s%d,", n++ % 24 == 0 ? "\n" : "", c);
        (void)fprintf(out, "\n};\n");
        (void)fclose(in);
    }
    (void)fputs("\nconst BundledMod bundled_mods[] = {\n", out);
    for (int i = 2; i < argc; i++) {
        char *eq = strchr(argv[i], '=');
        (void)fprintf(out, "    {\"%.*s\", src_%d, sizeof src_%d},\n", (int)(eq - argv[i]), argv[i], i - 2, i - 2);
    }
    (void)fputs("    {0, 0, 0}\n};\n", out);
    return fclose(out) != 0;
}
